// Skinned MakeHuman rower (CC0, generated by pipeline/make_rower.py). One continuous mesh, so knees and
// elbows bend like skin. Every frame the pose is solved afresh from the rest pose: the spine leans, the
// limbs are two-bone IK with fixed hinge directions, and the fingers wrap the handles. Nothing accumulates.
// All targets are in boat space (the model is a child of the boat).
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { BODY } from './rig.js';

const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const Q = () => new THREE.Quaternion();
const Y = V(0, 1, 0), ZAX = V(0, 0, 1);
const perp = (a, d) => a.clone().addScaledVector(d, -a.dot(d)); // part of a at right angles to unit d

// Middle joint of a two-bone chain. `pole` picks the bend direction.
export function ik(a, c, l1, l2, pole) {
  const ac = c.clone().sub(a); let d = ac.length(); d = Math.min(d, (l1 + l2) * .999); ac.normalize();
  const x = (l1 * l1 - l2 * l2 + d * d) / (2 * d), h = Math.sqrt(Math.max(0, l1 * l1 - x * x));
  return a.clone().addScaledVector(ac, x).addScaledVector(perp(pole, ac).normalize(), h);
}
// Rotation that takes local axes (yl, al) to world axes (yw, aw). The a axes are squared up first.
const _m1 = new THREE.Matrix4(), _m2 = new THREE.Matrix4();
function frame(yl, al, yw, aw) {
  const a1 = perp(al, yl).normalize(), a2 = perp(aw, yw).normalize();
  _m1.makeBasis(yl.clone().cross(a1), yl, a1); _m2.makeBasis(yw.clone().cross(a2), yw, a2);
  return Q().setFromRotationMatrix(_m2.multiply(_m1.transpose()));
}

export function createRower(boat, material) {
  const R = { ready: false, bones: {}, len: {} };
  const rest = {}, restL = {}, ax = {}, cur = new Map();
  let root, b;

  new GLTFLoader().load('/models/rower.glb', gltf => {
    root = gltf.scene; let mesh;
    root.traverse(o => { if (o.isSkinnedMesh) mesh = o; if (o.isBone) R.bones[o.name] = o; });
    b = R.bones;
    mesh.material = material; mesh.castShadow = true; mesh.receiveShadow = true; mesh.frustumCulled = false;
    mesh.geometry.computeBoundingBox();
    root.scale.setScalar(BODY.height / (mesh.geometry.boundingBox.max.y - mesh.geometry.boundingBox.min.y));
    root.rotation.y = -Math.PI / 2;   // the model faces +z; the rower faces the stern (-x)
    boat.add(root); boat.updateMatrixWorld(true);
    // Rest pose in boat space: orientation and position of every bone.
    const inv = boat.matrixWorld.clone().invert(), pos = {};
    const restQ = o => o === boat ? Q() : restQ(o.parent).multiply(o.quaternion);
    for (const n in b) { rest[n] = restQ(b[n]); restL[n] = b[n].quaternion.clone(); pos[n] = b[n].getWorldPosition(V()).applyMatrix4(inv); }
    const local = (n, w) => w.clone().applyQuaternion(rest[n].clone().invert());
    const dir = (p, q) => pos[q].clone().sub(pos[p]).normalize();
    for (const s of ['l', 'r']) {
      const T = 'thigh_' + s, C = 'calf_' + s, F = 'foot_' + s, U = 'upperarm_' + s, E = 'lowerarm_' + s, H = 'hand_' + s;
      R.len[T] = pos[T].distanceTo(pos[C]); R.len[C] = pos[C].distanceTo(pos[F]);
      R.len[U] = pos[U].distanceTo(pos[E]); R.len[E] = pos[E].distanceTo(pos[H]);
      ax[T] = local(T, V(-1, 0, 0)); ax[C] = local(C, V(-1, 0, 0));           // front of the leg
      ax[F] = local(F, V(0, -1, 0));                                            // sole of the foot
      const du = dir(U, E), df = dir(E, H);
      ax[U] = local(U, perp(df, du).normalize());                                // inside of the elbow
      ax[E] = local(E, perp(du.clone().negate(), df).normalize());
      // Hand: fingers run along `y`; the palm faces the way the fingers curl (their local +z).
      const fy = dir(H, 'middle_01_' + s), palm = V();
      for (const f of ['index', 'middle', 'ring']) palm.add(ZAX.clone().applyQuaternion(rest[f + '_01_' + s]));
      ax[H] = { y: local(H, fy), a: local(H, perp(palm, fy).normalize()) };
    }
    R.trunk = pos.upperarm_l.clone().add(pos.upperarm_r).multiplyScalar(.5).sub(pos.thigh_l.clone().add(pos.thigh_r).multiplyScalar(.5)).length();
    R.root = root; R.mesh = mesh; R.ready = true;
    if (import.meta.env?.DEV || location.search.includes('debug')) { window.__rw = R; console.log('rower', JSON.stringify(R.len), 'trunk', R.trunk.toFixed(3)); }
  });

  // Orientation of any node in boat space this frame.
  const get = o => { if (o === boat) return Q(); let q = cur.get(o); if (!q) { q = get(o.parent).multiply(o.quaternion); cur.set(o, q); } return q.clone(); };
  const set = (bone, q) => { bone.quaternion.copy(get(bone.parent).invert().multiply(q)); cur.set(bone, q.clone()); };
  const inv = new THREE.Matrix4();
  const at = n => b[n].getWorldPosition(V()).applyMatrix4(inv);
  const lean = a => Q().setFromAxisAngle(ZAX, a);

  // T: { hip: Vector3 (middle of the hip joints), lean, flex, head (radians), reach (m),
  //      sides: { l|r: { ankle, footDir, sole, grip, handle (unit, along the oar handle), pole, curl } } }
  R.pose = T => {
    if (!R.ready) return null;
    cur.clear();
    for (const n in b) b[n].quaternion.copy(restL[n]);
    // Spine: curved forward at the catch, long and open at the finish. Solved twice so the hip-to-shoulder line hits the lean exactly.
    const spine = d => {
      cur.clear();
      set(b.pelvis, lean(T.lean + d - T.flex * .75).multiply(rest.pelvis));
      set(b.spine_01, lean(T.lean + d - T.flex * .3).multiply(rest.spine_01));
      set(b.spine_02, lean(T.lean + d + T.flex * .25).multiply(rest.spine_02));
      set(b.spine_03, lean(T.lean + d + T.flex * .7).multiply(rest.spine_03));
      set(b.neck_01, lean((T.lean + d) * .55 + T.head).multiply(rest.neck_01));
      set(b.head, lean((T.lean + d) * .2 + T.head).multiply(rest.head));
    };
    const settle = () => {
      root.updateMatrixWorld(true); inv.copy(boat.matrixWorld).invert();
      const mid = at('thigh_l').add(at('thigh_r')).multiplyScalar(.5);
      root.position.add(T.hip.clone().sub(mid)); root.updateMatrixWorld(true);
      return at('upperarm_l').add(at('upperarm_r')).multiplyScalar(.5).sub(T.hip);
    };
    spine(0); let up = settle();
    spine(T.lean - Math.atan2(-up.x, up.y));
    // Shoulder blades slide round the ribs: forward to reach at the catch, back at the finish.
    const chestUp = Y.clone().applyQuaternion(lean(T.lean + T.flex * .7));
    for (const s of ['l', 'r']) { const sg = s == 'l' ? 1 : -1;
      set(b['clavicle_' + s], Q().setFromAxisAngle(chestUp, -sg * T.reach * 5.5).multiply(get(b.spine_03).multiply(restL['clavicle_' + s]))); }
    settle();
    const out = {};
    for (const s of ['l', 'r']) {
      const S = T.sides[s], n = k => b[k + '_' + s];
      // Leg
      const hip = at('thigh_' + s), knee = ik(hip, S.ankle, R.len['thigh_' + s], R.len['calf_' + s], S.kneePole);
      const dt = knee.clone().sub(hip).normalize(), dc = S.ankle.clone().sub(knee).normalize();
      set(n('thigh'), frame(Y, ax['thigh_' + s], dt, perp(dc, dt).negate()));
      set(n('calf'), frame(Y, ax['calf_' + s], dc, perp(dt, dc)));
      set(n('foot'), frame(Y, ax['foot_' + s], S.footDir, S.sole));
      // Arm: the wrist sits above and behind the handle so the fingers can wrap over it.
      const sh = at('upperarm_' + s), h = S.handle;
      const fd = perp(S.grip.clone().sub(sh), h).normalize();          // along the back of the hand, flat wrist
      let palm = fd.clone().cross(h); if (palm.y > 0) palm.negate();     // palm faces down on to the handle
      palm.applyAxisAngle(h, S.roll || 0); const fdr = fd.clone().applyAxisAngle(h, S.roll || 0);
      const wrist = S.grip.clone().addScaledVector(fdr, -BODY.grip).addScaledVector(palm, -.028);
      const elb = ik(sh, wrist, R.len['upperarm_' + s], R.len['lowerarm_' + s], S.pole);
      const du = elb.clone().sub(sh).normalize(), df = wrist.clone().sub(elb).normalize();
      set(n('upperarm'), frame(Y, ax['upperarm_' + s], du, perp(df, du)));
      const qf = frame(Y, ax['lowerarm_' + s], df, perp(du.clone().negate(), df));
      const qh = frame(ax['hand_' + s].y, ax['hand_' + s].a, fdr, palm);
      // Share the wrist's twist with the forearm so the skin does not wring at the wrist.
      const rel = qf.clone().invert().multiply(qh), rel0 = rest['lowerarm_' + s].clone().invert().multiply(rest['hand_' + s]);
      const dq = rel.multiply(rel0.invert()), tw = new THREE.Quaternion(0, dq.y, 0, dq.w).normalize();
      set(n('lowerarm'), qf.multiply(Q().slerp(tw, .55)));
      set(n('hand'), qh);
      // Fingers wrap the grip; the thumb sits over the end.
      const c = S.curl ?? 1;
      for (const f of ['index', 'middle', 'ring', 'pinky']) [1.15, 1.45, .8].forEach((a, i) => { const fb = n(f + '_0' + (i + 1)); fb.quaternion.copy(restL[fb.name]).multiply(Q().setFromAxisAngle(V(1, 0, 0), a * c)); });
      [.25, .45, .5].forEach((a, i) => { const fb = n('thumb_0' + (i + 1)); fb.quaternion.copy(restL[fb.name]).multiply(Q().setFromAxisAngle(V(1, 0, 0), a * c)); });
      out[s] = { hip, knee, ankle: S.ankle.clone(), sh, elb, hand: wrist };
    }
    root.updateMatrixWorld(true);
    for (const s in out) for (const k in out[s]) out[s][k].applyMatrix4(boat.matrixWorld); // hand back world positions
    out.head = b.head.getWorldPosition(V());
    return out;
  };
  return R;
}
